// [Blur2PC][macOS] Real normal+R32F prepass outputs, independent masks and pass transitions.
#include <core/core.h>
#include <core/maths.h>
#include <display.h>
#include <display/context/Context.h>
#include <display2/context/MetalOcclusion.h>
#include <cmath>
#include <cstring>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
static void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class F>static void rejects(F operation,const char* message){bool failed=false;try{operation();}catch(const std::logic_error&){failed=true;}require(failed,message);}
static std::vector<U8> shader(bool vertex,bool sampled=false){
    const std::string metadata=vertex?R"({"parameters":{},"input_semantics":[[0,0,0]],"reflection":{"ubos":[]}})":sampled?R"({"parameters":{},"input_semantics":[],"reflection":{"ubos":[],"textures":[{"binding":0,"type":"sampler2D"},{"binding":1,"type":"sampler2D"}]}})":R"({"parameters":{"normal":[0,1],"reverseDepth":[1,1]},"input_semantics":[],"reflection":{"ubos":[{"name":"PixelConstants","binding":0,"block_size":32}]}})";
    const std::string common="#include <metal_stdlib>\nusing namespace metal;\nstruct Varying {float4 position[[position]];float2 uv[[user(locn0)]];};\n";
    const std::string source=common+(vertex?
        "struct Input{float3 position[[attribute(0)]];};vertex Varying blur_main(Input input[[stage_in]]){return {float4(input.position,1),float2(.5+.5*input.position.x,.5-.5*input.position.y)};}\n":sampled?
        "fragment float4 blur_main(Varying input[[stage_in]],texture2d<float> normals[[texture(0)]],texture2d<float> depth[[texture(1)]],sampler n[[sampler(0)]],sampler d[[sampler(1)]]){float4 normal=normals.sample(n,input.uv);return float4(normal.r,normal.g,depth.sample(d,input.uv).r,1);}\n":
        "struct Outputs{float4 normal[[color(0)]];float reverseDepth[[color(1)]];};fragment Outputs blur_main(constant float4* values[[buffer(0)]]){return {values[0],values[1].x};}\n");
    const std::string entry="blur_main";std::vector<U8> bytes(40);std::memcpy(bytes.data(),"BMSL",4);auto word=[&](U32 offset,U32 value){for(U32 i=0;i<4;++i)bytes[offset+i]=U8(value>>(i*8));};word(4,1);word(8,vertex?0:1);word(16,40);word(20,metadata.size());word(24,40+metadata.size());word(28,source.size());word(32,40+metadata.size()+source.size());word(36,entry.size());bytes.insert(bytes.end(),metadata.begin(),metadata.end());bytes.insert(bytes.end(),source.begin(),source.end());bytes.insert(bytes.end(),entry.begin(),entry.end());word(12,bytes.size());return bytes;
}
static void colour(Display::C_Surface& surface,U32 expected){auto lock=surface.LockRect(16);require(lock.pBits,"MRT color readback failed");bool valid=true;for(U32 y=0;y<surface.GetHeight();++y)for(U32 x=0;x<surface.GetWidth();++x){U32 value;std::memcpy(&value,lock.pBits+y*lock.pitch+x*4,4);valid&=value==expected;}surface.UnlockRect();require(valid,"MRT normal/color pixels differ from independent expected values");}
static void depth(Display::C_Surface& surface,F32 expected,bool partial=false){auto lock=surface.LockRect(16);require(lock.pBits,"MRT R32F readback failed");bool valid=true;for(U32 y=0;y<surface.GetHeight();++y)for(U32 x=0;x<surface.GetWidth();++x){F32 value;std::memcpy(&value,lock.pBits+y*lock.pitch+x*4,4);const F32 target=partial&&x>=8&&x<24&&y>=4&&y<12?128.f/255:expected;valid&=std::isfinite(value)&&std::abs(value-target)<1e-6f;}surface.UnlockRect();require(valid,"MRT reverse depth floats differ from independent expected values");}
int main(){try{
    Display::C_Device device;Display::C_DeviceParams params;params.m_Width=32;params.m_Height=16;params.m_DepthStencilFormat=Display::E_Format_D16;require(device.Create(params)&&device.CreateVolatile(params),"Native MRT device creation failed");auto& gpu=device.GetDisplay2();auto& context=gpu.GetContext();
    Display::C_RenderTexture2D normal,reverse;require(device.CreateRenderTexture2D(32,16,1,Display::E_Usage_Colour,Display::E_Format_A8R8G8B8,Display::E_Multisample_None,nullptr,&normal),"Normal MRT allocation failed");require(device.CreateRenderTexture2D(32,16,1,Display::E_Usage_Colour,Display::E_Format_R32F,Display::E_Multisample_None,nullptr,&reverse),"Reverse-depth MRT allocation failed");
    Display::C_Surface normalCopy,depthCopy,wrongSize;require(device.CreateSurface(32,16,Display::E_Usage_Colour,Display::E_Format_A8R8G8B8,Display::E_Multisample_None,nullptr,&normalCopy)&&device.CreateSurface(32,16,Display::E_Usage_Colour,Display::E_Format_R32F,Display::E_Multisample_None,nullptr,&depthCopy)&&device.CreateSurface(16,16,Display::E_Usage_Colour,Display::E_Format_R32F,Display::E_Multisample_None,nullptr,&wrongSize),"MRT copy/validation targets failed");
    Display::C_VertexShader vs;Display::C_PixelShader ps,post;std::string error;auto v=shader(true),p=shader(false),s=shader(false,true);require(gpu.CreateVertexShader(v.size(),v.data(),0,&vs,nullptr,&error),error.c_str());require(gpu.CreatePixelShader(p.size(),p.data(),0,&ps,nullptr,&error),error.c_str());require(gpu.CreatePixelShader(s.size(),s.data(),0,&post,nullptr,&error),error.c_str());
    Display2::C_VertexFormat f;f.AddElement(0,0,Display2::E_VertexElementType_F32_3,Display2::E_VertexElementUsage_Position,0);Display::C_VertexDeclaration declaration;require(gpu.CreateVertexDeclaration(f,&declaration),"MRT vertex declaration failed");Display::C_VertexBuffer vertices;const F32 positions[]={-1,1,.75f,1,1,.75f,-1,-1,.75f,1,-1,.75f};require(gpu.CreateVertexBuffer(sizeof(positions),0,&vertices),"MRT vertices failed");void* data=vertices.Lock();require(data,"MRT vertex upload failed");std::memcpy(data,positions,sizeof(positions));vertices.Unlock();
    auto bind=[&]{device.SetColourSurface(0,&normal.GetSurface());device.SetColourSurface(1,&reverse.GetSurface());device.SetColourSurface(2,nullptr);device.SetColourSurface(3,nullptr);device.SetDepthStencilSurface(device.GetNativeDepthSurface());context.SetVertexShader(&vs);context.SetPixelShader(&ps);context.SetVertexBuffer(0,&vertices,0,12,&declaration);context.SetCullMode(Display2::E_CullMode_None);context.SetDepthEnable(Display2::E_Bool_True);context.SetDepthWriteEnable(Display2::E_Bool_True);context.SetDepthFunc(Display2::E_CmpFunc_GreaterEqual);context.SetBlendEnable(Display2::E_Bool_False);};
    auto values=[&](bool second){const F32 first[]={.25f,.5f,.75f,1,.75f,0,0,0},next[]={.75f,.25f,.5f,1,.25f,0,0,0};context.SetPixelShaderConstantF(0,second?next:first,2);};auto draw=[&]{context.DrawPrimitive(Display2::E_PrimitiveType_TriangleStrip,0,4);};
    Display2::C_OcclusionQuery query;require(query.Create(context),"MRT visibility query failed");
    require(device.BeginScene(),"MRT scene failed");bind();require(device.GetRenderTarget().GetColourSurface(0)==&normal.GetSurface()&&device.GetRenderTarget().GetColourSurface(1)==&reverse.GetSurface()&&device.GetRenderTarget().GetColourFormat(1)==Display::E_Format_R32F&&device.GetRenderTarget().GetColourWidth(1)==32,"Upper MRT metadata lost a bound attachment");
    context.Clear(Display2::E_Clear_Colour|Display2::E_Clear_Depth,0xff000000,0);values(false);query.Begin();draw();query.End();device.EndScene();U64 samples=0;require(query.GetResult(samples)&&samples==512,"MRT query counted render targets instead of visible samples");colour(normal.GetSurface(),0xff4080bf);depth(reverse.GetSurface(),.75f);
    require(device.BeginScene(),"Masked MRT scene failed");bind();values(true);device.SetColourWriteEnable(0,Display::E_ColourWriteEnable_Green);device.SetColourWriteEnable(1,Display::E_ColourWriteEnable_None);require(device.GetColourWriteEnable(0)==2&&device.GetColourWriteEnable(1)==0,"Native MRT mask state was not independent");draw();device.EndScene();colour(normal.GetSurface(),0xff4040bf);depth(reverse.GetSurface(),.75f);
    require(device.BeginScene(),"Global MRT mask restore failed");bind();values(true);device.SetColourWriteEnable(Display::E_ColourWriteEnable_All);require(context.GetColourWriteEnable(0)==15&&context.GetColourWriteEnable(1)==15,"Legacy global write mask failed to reset every MRT");draw();device.EndScene();colour(normal.GetSurface(),0xffbf4080);depth(reverse.GetSurface(),.25f);
    require(device.BeginScene(),"Disabled MRT writes scene failed");bind();values(false);device.SetColourWriteEnable(Display::E_ColourWriteEnable_None);draw();context.SetViewport(Display2::C_Viewport(8,4,16,8));context.Clear(Display2::E_Clear_Colour,0xff800000);device.EndScene();depth(reverse.GetSurface(),.25f,true);
    require(device.BeginScene(),"MRT transition scene failed");bind();values(false);context.Clear(Display2::E_Clear_Colour|Display2::E_Clear_Depth,0xff000000,0);query.Begin();draw();context.CopySurface(&normalCopy,&normal.GetSurface());context.CopySurface(&depthCopy,&reverse.GetSurface());
    device.SetColourDepthStencilSurface();for(U32 i=1;i<4;++i)require(!device.GetRenderTarget().GetColourSurface(i),"Single-target transition retained upper MRT attachment metadata");context.SetPixelShader(&post);context.SetTexture(0,&normal.GetTexture());context.SetTexture(1,&reverse.GetTexture());Display2::C_SamplerState sampler;sampler.SetTextureAddress(Display2::E_TextureAddress_Clamp);context.SetSamplerState(0,sampler);context.SetSamplerState(1,sampler);context.SetDepthEnable(Display2::E_Bool_False);draw();query.End();device.EndScene();require(query.GetResult(samples)&&samples==1024,"MRT/copy/single-target transition lost query segments");colour(*device.GetNativeColourSurface(),0xff4080bf);colour(normalCopy,0xff4080bf);depth(depthCopy,.75f);
    require(device.BeginScene(),"MRT validation scene failed");bind();device.SetColourSurface(1,&wrongSize);rejects([&]{context.Clear(Display2::E_Clear_Colour,0);},"Mismatched MRT dimensions were accepted");device.SetColourSurface(1,&normal.GetSurface());rejects([&]{context.Clear(Display2::E_Clear_Colour,0);},"Aliased MRT attachments were accepted");device.SetColourSurface(1,&reverse.GetSurface());context.SetPixelShader(&post);context.SetTexture(0,&normal.GetTexture());context.SetTexture(1,&reverse.GetTexture());rejects(draw,"Still-attached MRT texture was sampled as postprocess input");device.SetColourDepthStencilSurface();device.EndScene();
    device.Destroy(&normal);device.Destroy(&reverse);device.Destroy(&normalCopy);device.Destroy(&depthCopy);device.Destroy(&wrongSize);device.Destroy(&vs);device.Destroy(&ps);device.Destroy(&post);device.Destroy(&vertices);gpu.Destroy(&declaration);require(gpu.WaitIdle(),"MRT GPU commands failed");device.DestroyVolatile();device.Destroy();
    std::cout<<"Native MRT: actual BGRA normals + R32F reverse depth, reverse Z, independent/global masks, partial clears, copies, sampled pass transition, visibility and invalid attachment rejection passed\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
